from collections import deque

def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize an empty list to store tuples of planets
    planets = []

    # Use deque for efficient pop from the back
    dq = deque()

    # Add planets with orbits between planet1 and planet2 to the deque
    dq.append((planet1, 0))
    dq.append((planet2, 0))

    while dq:
        current_planet, distance = dq.popleft()

        # If the current planet's orbit is between planet1 and planet2, add it to the list
        if current_planet[distance] < (distance + 1) / 2:
            planets.append(current_planet)

        # Move to the next planet in the sequence
        if current_planet[distance] > (distance + 1) / 2:
            dq.appendleft(current_planet)

    return tuple(planets)


